package com.emssystem.emsleaveservice.pto.entity; import com.emssystem.emsleaveservice.shared.entity.AuditableEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="pto_balances",uniqueConstraints=@UniqueConstraint(name="uk_pto_balance_employee_type",columnNames={"employee_id","pto_type_id"})) public class PtoBalance extends AuditableEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="employee_id",nullable=false) private Long employeeId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="pto_type_id",nullable=false) private PtoType ptoType;@Column(name="accrued_hours",nullable=false,precision=10,scale=2) private BigDecimal accruedHours=BigDecimal.ZERO;@Column(name="used_hours",nullable=false,precision=10,scale=2) private BigDecimal usedHours=BigDecimal.ZERO;@Column(name="reserved_hours",nullable=false,precision=10,scale=2) private BigDecimal reservedHours=BigDecimal.ZERO;protected PtoBalance(){}public PtoBalance(Long employeeId,PtoType type){this.employeeId=employeeId;this.ptoType=type;}public Long getId(){return id;}public Long getEmployeeId(){return employeeId;}public PtoType getPtoType(){return ptoType;}public BigDecimal getAccruedHours(){return accruedHours;}public BigDecimal getUsedHours(){return usedHours;}public BigDecimal getReservedHours(){return reservedHours;}}
